<section class="campaign-hero card shadow-sm border-0 mb-4"><div class="card-body p-4 p-lg-5"><span class="badge badge-light mb-2"><?= $campaign['owner_merchant_id']===null?'Campaign nền tảng':'Campaign Merchant' ?></span><h1 class="display-4 font-weight-bold mb-2"><?= e((string)$campaign['name']) ?></h1><?php if(!empty($campaign['description'])):?><p class="lead mb-3"><?= e((string)$campaign['description']) ?></p><?php endif;?><div><i class="fa-regular fa-calendar mr-1"></i><?= e(format_db_datetime((string)$campaign['starts_at'])) ?> → <?= e(format_db_datetime((string)$campaign['ends_at'])) ?></div></div></section>
<h2 class="h4 mb-3">Deal trong Campaign</h2><div class="row"><?php if($coupons===[]):?><div class="col-12"><div class="alert alert-info">Campaign chưa có coupon ACTIVE.</div></div><?php endif;?><?php foreach($coupons as $coupon):?><div class="col-md-6 col-lg-4 mb-4"><div class="card coupon-card h-100 shadow-sm"><div class="card-body d-flex flex-column"><div class="mb-2"><span class="badge-soft <?= e(category_badge_class((string)$coupon['category_name'])) ?>"><?= e((string)$coupon['category_name']) ?></span> <span class="badge-soft <?= e(usage_badge_class((string)$coupon['usage_channel'])) ?>"><?= e(usage_channel_label((string)$coupon['usage_channel'])) ?></span></div><h3 class="h5"><?= e((string)$coupon['title']) ?></h3><div class="small text-muted mb-3"><?= e((string)$coupon['merchant_name']) ?></div><div class="coupon-discount"><?= e(format_discount($coupon)) ?></div><div class="mt-auto pt-3"><a class="btn btn-outline-primary btn-sm" href="<?= e(url('/coupons/'.(int)$coupon['id'])) ?>">Xem deal</a></div></div></div></div><?php endforeach;?></div>
